private String backupReason(String reason) {
    if (reason == null || reason.isBlank()) {
        return FindMeAuiManageScreen.tr("screen.find_me.doctor.backup_reason.unknown", new Object[0]);
    }
    String normalized = reason.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "_");
    String key = "screen.find_me.doctor.backup_reason." + normalized;
    String translated = FindMeAuiManageScreen.tr(key, new Object[0]);
    return translated.equals(key) ? reason : translated;
}

private String backupDisplayName(DoctorPagePacket.Backup backup) {
    if (BackupFilter.AUTOMATIC.matches(backup)) {
        return FindMeAuiManageScreen.tr("screen.find_me.doctor.automatic_backup", new Object[0]);
    }
    String reason = backup.reason();
    if (backup.manual() && (reason == null || reason.isBlank() || "manual".equalsIgnoreCase(reason) || "aui_manual".equalsIgnoreCase(reason))) {
        return FindMeAuiManageScreen.tr("screen.find_me.doctor.manual_backup", new Object[0]);
    }
    String displayReason = this.backupReason(reason);
    return displayReason.isBlank() ? FindMeAuiManageScreen.tr("screen.find_me.doctor.other_backup", new Object[0]) : displayReason;
}

private String backupRenameValue(DoctorPagePacket.Backup backup) {
    String reason = backup.reason();
    return reason == null || reason.isBlank() || "manual".equalsIgnoreCase(reason) || "aui_manual".equalsIgnoreCase(reason) ? FindMeAuiManageScreen.tr("screen.find_me.doctor.manual_backup", new Object[0]) : reason;
}

private String backupDateLabel(DoctorPagePacket.Backup backup) {
    long timestamp = backup.createdAtEpochMillis();
    if (timestamp > 0L) {
        String date = BACKUP_DATE_FORMAT.format(Instant.ofEpochMilli(timestamp).atZone(ZoneId.systemDefault()));
        return FindMeAuiManageScreen.tr("screen.find_me.doctor.saved_at", date);
    }
    return FindMeAuiManageScreen.tr("screen.find_me.doctor.legacy_saved_tick", backup.savedAt());
}

