private CompanionEffectStyle effectStyle(UUID uuid, CompanionEffectPurpose purpose) {
    if (this.category == Category.VEHICLE) {
        for (VehicleListPacket.Entry entry : ClientVehicleState.allEntries()) {
            if (!entry.uuid().equals(uuid)) continue;
            return switch (purpose) {
                default -> throw new IncompatibleClassChangeError();
                case CompanionEffectPurpose.SUMMON -> entry.summonStyle();
                case CompanionEffectPurpose.RESCUE -> entry.rescueStyle();
                case CompanionEffectPurpose.STORAGE -> entry.storageStyle();
            };
        }
    } else {
        CompanionKind kind = this.category == Category.MOUNT ? CompanionKind.MOUNT : CompanionKind.COMPANION;
        for (CompanionListPacket.Entry entry : ClientCompanionState.allEntries(kind)) {
            if (!entry.uuid().equals(uuid)) continue;
            return switch (purpose) {
                default -> throw new IncompatibleClassChangeError();
                case CompanionEffectPurpose.SUMMON -> entry.summonStyle();
                case CompanionEffectPurpose.RESCUE -> entry.rescueStyle();
                case CompanionEffectPurpose.STORAGE -> entry.storageStyle();
            };
        }
    }
    return CompanionEffectStyle.NONE;
}

